  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-portuguese-compare-sources-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"LIBRARY_HOURS","statement":"Aviso da biblioteca: “A sala de leitura fecha às 17h”. Comunicado da coordenação: “A sala será usada para reunião até 17h”.\n\nO que cada texto destaca?","options":["O aviso informa o horário de funcionamento; o comunicado informa um uso específico da sala.","Ambos provam que a sala ficou fechada todos os dias.","O comunicado repete integralmente o aviso.","Os textos têm o mesmo objetivo porque citam a sala."],"correctAnswer":"O aviso informa o horário de funcionamento; o comunicado informa um uso específico da sala.","explanation":"Um texto apresenta horário de atendimento; o outro, uma ocupação. Nenhum descreve todos os dias.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"SOURCE_FOCUS_COLLAPSED","misconceptions":{"Ambos provam que a sala ficou fechada todos os dias.":["SOURCE_FOCUS_COLLAPSED"]},"position":1},{"id":"v5-portuguese-compare-sources-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"DISTINGUISH","contextFamily":"BUS_WAIT","statement":"Relato: “Esperei vinte minutos no ponto”. Registro: “O ônibus saiu do terminal às 8h05”.\n\nPor que as informações não se contradizem necessariamente?","options":["A saída às 8h05 prova que não houve espera.","Uma descreve espera em um ponto; a outra registra a saída do terminal, sem informar o horário previsto.","O relato prova atraso de todos os ônibus.","O registro explica sozinho a experiência da passageira."],"correctAnswer":"Uma descreve espera em um ponto; a outra registra a saída do terminal, sem informar o horário previsto.","explanation":"Os registros tratam de eventos e locais distintos. Para medir atraso, falta o horário previsto e o trajeto.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"DIFFERENT_EVENTS_MISTAKEN_FOR_CONTRADICTION","misconceptions":{"A saída às 8h05 prova que não houve espera.":["DIFFERENT_EVENTS_MISTAKEN_FOR_CONTRADICTION"]},"position":2},{"id":"v5-portuguese-compare-sources-03","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"GARDEN","statement":"Estudante: “A horta me ajudou a observar insetos”. Inventário: “Há quatro canteiros e duas ferramentas”.\n\nQual síntese preserva o tipo de evidência de cada fonte?","options":["O inventário prova o que todos aprenderam.","O relato confirma a quantidade de canteiros.","O relato registra uma aprendizagem individual; o inventário descreve itens e estruturas listados.","As fontes são equivalentes porque falam da mesma horta."],"correctAnswer":"O relato registra uma aprendizagem individual; o inventário descreve itens e estruturas listados.","explanation":"Experiência relatada e inventário respondem a perguntas diferentes; uma fonte não substitui a outra.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"GENRE_CONFUSED_WITH_EVIDENCE","misconceptions":{"O inventário prova o que todos aprenderam.":["GENRE_CONFUSED_WITH_EVIDENCE"]},"position":3},{"id":"v5-portuguese-compare-sources-04","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"DISTINGUISH","contextFamily":"PARK_BENCH","statement":"Moradora: “Sento aqui para descansar”. Manutenção: “Um banco está com uma tábua solta”.\n\nO que se pode concluir sem generalizar?","options":["A praça inteira é inutilizável.","Todos os bancos estão em boas condições.","Ninguém usa a praça.","Há uma experiência de descanso relatada e um defeito localizado em um banco."],"correctAnswer":"Há uma experiência de descanso relatada e um defeito localizado em um banco.","explanation":"As afirmações podem coexistir e têm alcances diferentes: uma experiência e uma observação localizada.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"LOCAL_EVIDENCE_GENERALIZED","misconceptions":{"A praça inteira é inutilizável.":["LOCAL_EVIDENCE_GENERALIZED"]},"position":4},{"id":"v5-portuguese-compare-sources-05","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"MARKET","statement":"Feirante: “A feira é um lugar de encontro”. Relatório: “A feira concentra circulação aos sábados”.\n\nQue diferença de foco aparece?","options":["A feirante destaca convivência; o relatório destaca circulação em um dia definido.","Uma fonte está errada porque usa outra expressão.","O relatório representa diretamente a opinião da feirante.","As frases descrevem igualmente todas as experiências."],"correctAnswer":"A feirante destaca convivência; o relatório destaca circulação em um dia definido.","explanation":"Os textos observam o mesmo espaço por objetivos distintos; nenhum resume todas as experiências.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"DIFFERENT_FOCUS_FORCED_INTO_CONFLICT","misconceptions":{"Uma fonte está errada porque usa outra expressão.":["DIFFERENT_FOCUS_FORCED_INTO_CONFLICT"]},"position":1},{"id":"v5-portuguese-compare-sources-06","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"BRIDGE","statement":"Moradora: “A ponte encurtou meu caminho”. Nota técnica: “A ponte tem 18 metros”.\n\nQue dado verificaria quanto o trajeto foi encurtado?","options":["A cor da ponte.","Medidas dos percursos antes e depois, entre pontos de partida e chegada comparáveis.","A extensão da ponte tratada como redução do trajeto.","A conclusão de que todos economizam 18 metros."],"correctAnswer":"Medidas dos percursos antes e depois, entre pontos de partida e chegada comparáveis.","explanation":"A extensão da estrutura não informa a diferença entre rotas. É preciso comparar percursos equivalentes.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"STRUCTURE_LENGTH_CONFUSED_WITH_ROUTE_CHANGE","misconceptions":{"A cor da ponte.":["STRUCTURE_LENGTH_CONFUSED_WITH_ROUTE_CHANGE"]},"position":2},{"id":"v5-portuguese-compare-sources-07","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"SCHOOL_MEETING","statement":"Ata: “A reunião começou às 16h e aprovou a proposta”. Bilhete: “Saí às 16h30”.\n\nO que a comparação permite afirmar?","options":["A pessoa votou a favor por estar no início.","A reunião terminou às 16h30.","A ata registra início e decisão; o bilhete registra a saída de uma pessoa, sem dizer se ela participou da votação.","O bilhete invalida automaticamente a ata."],"correctAnswer":"A ata registra início e decisão; o bilhete registra a saída de uma pessoa, sem dizer se ela participou da votação.","explanation":"Sem horário da votação e lista de presença, não se sabe como a pessoa participou.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"PRESENCE_INFERRED_FROM_PARTIAL_RECORD","misconceptions":{"A pessoa votou a favor por estar no início.":["PRESENCE_INFERRED_FROM_PARTIAL_RECORD"]},"position":3},{"id":"v5-portuguese-compare-sources-08","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"STREET_NAME","statement":"Mapa de 1980: “Rua do Mercado”. Guia de 2020: “Rua das Palmeiras” para o mesmo trecho.\n\nO que deve ser investigado antes de declarar um mapa errado?","options":["A rua necessariamente deixou de existir.","O mapa recente é sempre correto.","O mercado ainda funciona.","Mudança oficial de nome, convenção cartográfica ou diferença na identificação do trecho."],"correctAnswer":"Mudança oficial de nome, convenção cartográfica ou diferença na identificação do trecho.","explanation":"Nomes distintos podem decorrer de mudança, convenção ou erro. Compare data, trecho e procedência.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"LABEL_CHANGE_ASSUMED_TO_PROVE_DISAPPEARANCE","misconceptions":{"A rua necessariamente deixou de existir.":["LABEL_CHANGE_ASSUMED_TO_PROVE_DISAPPEARANCE"]},"position":4},{"id":"v5-portuguese-compare-sources-09","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"FLOOD_REPORT","statement":"Moradora: “A água entrou em casa na terça à noite”. Boletim: “A estação do centro marcou 1,2 m às 21h”.\n\nComo combinar as fontes com cuidado?","options":["Relacionar o relato à casa e ao período e tratar a leitura como medida daquele ponto, não de toda a cidade.","Usar a estação como medida de todas as casas.","Descartar o relato por não informar centímetros.","Concluir que a leitura causou a entrada de água."],"correctAnswer":"Relacionar o relato à casa e ao período e tratar a leitura como medida daquele ponto, não de toda a cidade.","explanation":"Locais e escalas diferem. O boletim não substitui a experiência localizada.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"MEASUREMENT_POINT_GENERALIZED","misconceptions":{"Usar a estação como medida de todas as casas.":["MEASUREMENT_POINT_GENERALIZED"]},"position":5},{"id":"v5-portuguese-compare-sources-10","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"WORKSHOP_RULE","statement":"Regra: “Devolva as ferramentas ao fim do dia”. Relato: “Usei a ferramenta por uma semana”.\n\nQual leitura distingue prescrição e experiência?","options":["A regra prova que todos devolveram no dia.","A regra prescreve devolução diária; o relato descreve uma experiência que precisa de contexto.","O relato prova que a regra não existia.","A pessoa descumpriu a regra intencionalmente."],"correctAnswer":"A regra prescreve devolução diária; o relato descreve uma experiência que precisa de contexto.","explanation":"Uma norma registra o que deveria ocorrer; um relato registra um caso, mas não explica sua causa.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"NORM_TREATED_AS_UNIFORM_PRACTICE","misconceptions":{"A regra prova que todos devolveram no dia.":["NORM_TREATED_AS_UNIFORM_PRACTICE"]},"position":6},{"id":"v5-portuguese-compare-sources-11","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"NEWSPAPER","statement":"Notícia: “A reunião ocorreu na terça e reuniu 18 pessoas”. Editorial: “A proposta deveria ser revista”.\n\nO que muda entre os textos?","options":["O editorial comprova consenso entre participantes.","A notícia é neutra em cada escolha de informação.","A notícia relata informações do encontro; o editorial apresenta uma posição argumentada.","Os textos têm a mesma finalidade."],"correctAnswer":"A notícia relata informações do encontro; o editorial apresenta uma posição argumentada.","explanation":"Gênero e finalidade diferem. Um editorial representa uma posição, não o consenso de todos.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"EDITORIAL_POSITION_MISTAKEN_FOR_CONSENSUS","misconceptions":{"O editorial comprova consenso entre participantes.":["EDITORIAL_POSITION_MISTAKEN_FOR_CONSENSUS"]},"position":7},{"id":"v5-portuguese-compare-sources-12","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"ACCESS_RAMP","statement":"Pessoa usuária: “A rampa facilitou minha entrada”. Vistoria: “Inclinação medida: 9% neste trecho”.\n\nQue pergunta a vistoria não responde sozinha?","options":["Qual foi a inclinação medida.","Se a vistoria registrou 9%.","Se existe rampa no local.","Se o percurso completo é acessível em diferentes condições e atende aos critérios de uso aplicáveis."],"correctAnswer":"Se o percurso completo é acessível em diferentes condições e atende aos critérios de uso aplicáveis.","explanation":"A medida informa um trecho e um parâmetro; experiência e outros critérios avaliam o percurso completo.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"SINGLE_METRIC_USED_AS_COMPLETE_ACCESSIBILITY","misconceptions":{"Qual foi a inclinação medida.":["SINGLE_METRIC_USED_AS_COMPLETE_ACCESSIBILITY"]},"position":8},{"id":"v5-portuguese-compare-sources-13","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"BUS_ROUTE","statement":"Comunicado: “A linha terá novo itinerário a partir de segunda”. Mensagem: “Meu ponto habitual não aparece no mapa”.\n\nQue verificação ajuda a explicar a diferença?","options":["Comparar a versão e a data do mapa com o itinerário que entra em vigor.","Concluir que a linha foi cancelada.","Assumir que o comunicado trata de outra cidade.","Dizer que o ponto deixou de existir sem conferir a rota."],"correctAnswer":"Comparar a versão e a data do mapa com o itinerário que entra em vigor.","explanation":"Um mapa desatualizado pode não refletir a mudança. Data e versão são relevantes.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"SOURCE_DATE_IGNORED","misconceptions":{"Concluir que a linha foi cancelada.":["SOURCE_DATE_IGNORED"]},"position":9},{"id":"v5-portuguese-compare-sources-14","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"CANTEEN_MENU","statement":"Cardápio: “Opção vegetariana na quinta”. Pesquisa: “12 de 20 respondentes querem mais opções”.\n\nQual conclusão respeita as duas fontes?","options":["Todos são vegetarianos.","O cardápio anuncia uma opção para quinta; a pesquisa registra preferência entre 20 respondentes.","A opção estará disponível diariamente.","A pesquisa prova variedade suficiente."],"correctAnswer":"O cardápio anuncia uma opção para quinta; a pesquisa registra preferência entre 20 respondentes.","explanation":"Anúncio de uma data e respostas de um grupo delimitado têm escopos distintos.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"SAMPLE_AND_SCOPE_OMITTED","misconceptions":{"Todos são vegetarianos.":["SAMPLE_AND_SCOPE_OMITTED"]},"position":10},{"id":"v5-portuguese-compare-sources-15","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"WATER_USE","statement":"Cartaz: “Feche a torneira ao ensaboar”. Medição: “Fluxo de 6 litros por minuto nesta torneira”.\n\nO que a medição acrescenta?","options":["A água economizada por toda a escola.","A prova de que todos seguem o cartaz.","Uma taxa de fluxo daquele ponto; estimar volume exige também conhecer o tempo de uso.","O consumo diário de cada pessoa."],"correctAnswer":"Uma taxa de fluxo daquele ponto; estimar volume exige também conhecer o tempo de uso.","explanation":"Fluxo por minuto só permite estimar volume com duração e condições pertinentes.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"RATE_TREATED_AS_TOTAL","misconceptions":{"A água economizada por toda a escola.":["RATE_TREATED_AS_TOTAL"]},"position":11},{"id":"v5-portuguese-compare-sources-16","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"COMMUNITY_GARDEN","statement":"Ata: “Aprovado o uso de dois canteiros”. Entrevista: “Eu gostaria de plantar no terceiro”.\n\nQue diferença é sustentada?","options":["O terceiro canteiro foi aprovado.","A pessoa representa toda a comunidade.","A entrevista prova que a ata é falsa.","A ata registra uma decisão sobre dois canteiros; a entrevista expressa preferência individual sobre outro."],"correctAnswer":"A ata registra uma decisão sobre dois canteiros; a entrevista expressa preferência individual sobre outro.","explanation":"Decisão registrada e preferência individual são afirmações diferentes.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"PREFERENCE_MISTAKEN_FOR_DECISION","misconceptions":{"O terceiro canteiro foi aprovado.":["PREFERENCE_MISTAKEN_FOR_DECISION"]},"position":12},{"id":"v5-portuguese-compare-sources-17","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"SQUARE_EVENT","statement":"Organizadora: “Haverá três apresentações”. Comerciante: “A entrada ficará bloqueada na montagem, das 14h às 15h”.\n\nQual análise preserva o recorte?","options":["O evento prevê apresentações; o relato indica bloqueio localizado durante uma hora de montagem.","A loja ficará inacessível durante todo o evento.","Todas as pessoas serão beneficiadas igualmente.","Uma afirmação torna a outra falsa."],"correctAnswer":"O evento prevê apresentações; o relato indica bloqueio localizado durante uma hora de montagem.","explanation":"As fontes destacam programação e impacto localizado em horário específico.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"TIME_SCOPE_EXPANDED","misconceptions":{"A loja ficará inacessível durante todo o evento.":["TIME_SCOPE_EXPANDED"]},"position":1},{"id":"v5-portuguese-compare-sources-18","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"APPLY","contextFamily":"CLINIC_QUEUE","statement":"Painel: “Espera mediana: 32 minutos”. Relato: “Esperei quase uma hora ontem”.\n\nPor que os dados podem coexistir?","options":["Ninguém esperou mais de 32 minutos.","A mediana resume um conjunto; o relato descreve uma experiência individual.","O relato invalida toda a medição.","Ambos medem a mesma observação."],"correctAnswer":"A mediana resume um conjunto; o relato descreve uma experiência individual.","explanation":"Uma medida de centro não descreve cada caso. Data, amostra e distribuição importam.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"MEDIAN_MISTAKEN_FOR_EVERY_CASE","misconceptions":{"Ninguém esperou mais de 32 minutos.":["MEDIAN_MISTAKEN_FOR_EVERY_CASE"]},"position":2},{"id":"v5-portuguese-compare-sources-19","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"ENERGY_NOTICE","statement":"Fatura: “Consumo: 420 kWh em abril”. Comunicado: “Lâmpadas trocadas em maio”.\n\nO que não se conclui apenas desses textos?","options":["Que a fatura registrou 420 kWh.","Que a troca ocorreu em maio.","Que a troca reduziu o consumo: falta medida posterior comparável e análise de outros fatores.","Que os textos tratam do prédio."],"correctAnswer":"Que a troca reduziu o consumo: falta medida posterior comparável e análise de outros fatores.","explanation":"Ordem temporal não demonstra causalidade. Compare condições e períodos.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"SEQUENCE_MISTAKEN_FOR_CAUSATION","misconceptions":{"Que a fatura registrou 420 kWh.":["SEQUENCE_MISTAKEN_FOR_CAUSATION"]},"position":3},{"id":"v5-portuguese-compare-sources-20","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"BUS_ACCESS","statement":"Mapa: “Ponto acessível na avenida”. Relato: “Não encontrei rebaixo na calçada junto ao ponto”.\n\nQual síntese é mais fiel?","options":["O percurso inteiro é acessível porque o mapa diz.","O mapa inteiro está incorreto.","A barreira não importa se o ônibus é acessível.","O mapa classifica o ponto; o relato aponta uma barreira no acesso local que merece verificação."],"correctAnswer":"O mapa classifica o ponto; o relato aponta uma barreira no acesso local que merece verificação.","explanation":"Ponto indicado e percurso para alcançá-lo são dimensões relacionadas, não idênticas.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"ACCESS_LABEL_TREATED_AS_COMPLETE_ROUTE","misconceptions":{"O percurso inteiro é acessível porque o mapa diz.":["ACCESS_LABEL_TREATED_AS_COMPLETE_ROUTE"]},"position":4},{"id":"v5-portuguese-compare-sources-21","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"APPLY","contextFamily":"CLASS_SURVEY","statement":"Tabela: “15 de 24 preferem leitura em grupo”. Comentário: “Prefiro ler sozinho para me concentrar”.\n\nO que se pode afirmar?","options":["Na turma pesquisada, 15 de 24 escolheram grupo; há ao menos um relato com preferência diferente.","Todos preferem leitura em grupo.","O comentário prova que a tabela está errada.","A tabela mostra qual método gera melhores notas."],"correctAnswer":"Na turma pesquisada, 15 de 24 escolheram grupo; há ao menos um relato com preferência diferente.","explanation":"A contagem descreve respostas à pergunta; não mede resultados de aprendizagem.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"PREFERENCE_SURVEY_CONFUSED_WITH_OUTCOME","misconceptions":{"Todos preferem leitura em grupo.":["PREFERENCE_SURVEY_CONFUSED_WITH_OUTCOME"]},"position":5},{"id":"v5-portuguese-compare-sources-22","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"MUSEUM_LABEL","statement":"Legenda: “Objeto usado em atividades cotidianas”. Ficha: “Cerâmica; datação estimada entre 1900 e 1950”.\n\nQue detalhe exige evidência adicional?","options":["Que o material é cerâmica.","Qual atividade cotidiana específica era realizada; isso não está informado.","Que a datação é estimada.","Que a legenda oferece uma interpretação funcional."],"correctAnswer":"Qual atividade cotidiana específica era realizada; isso não está informado.","explanation":"Material e intervalo estão explícitos; uma função específica não pode ser inventada.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"FUNCTIONAL_DETAIL_INVENTED","misconceptions":{"Que o material é cerâmica.":["FUNCTIONAL_DETAIL_INVENTED"]},"position":6},{"id":"v5-portuguese-compare-sources-23","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"WEATHER_ALERT","statement":"Alerta: “Possibilidade de chuva forte no município”. Diário: “Não choveu no bairro pela manhã”.\n\nComo avaliar as afirmações?","options":["O diário prova alerta falso no município inteiro.","O alerta prova chuva naquele bairro.","O alerta expressa possibilidade para uma área; o diário relata observação local pela manhã.","Possibilidade significa ocorrência."],"correctAnswer":"O alerta expressa possibilidade para uma área; o diário relata observação local pela manhã.","explanation":"Probabilidade, espaço e horário são recortes diferentes.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"FORECAST_SCOPE_MISTAKEN_FOR_EVENT","misconceptions":{"O diário prova alerta falso no município inteiro.":["FORECAST_SCOPE_MISTAKEN_FOR_EVENT"]},"position":7},{"id":"v5-portuguese-compare-sources-24","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"APPLY","contextFamily":"REPAIR_REQUEST","statement":"Protocolo: “Pedidos urgentes terão prioridade”. Painel: “Pedido recebido às 10h12; aguardando análise”.\n\nO que o painel não permite concluir?","options":["Que foi recebido às 10h12.","Que o status é aguardando análise.","Que há um protocolo de prioridade.","Que o pedido foi classificado como urgente ou que a prioridade já foi aplicada."],"correctAnswer":"Que o pedido foi classificado como urgente ou que a prioridade já foi aplicada.","explanation":"O painel não mostra classificação nem decisão para este pedido.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"GENERAL_RULE_ASSUMED_APPLIED","misconceptions":{"Que foi recebido às 10h12.":["GENERAL_RULE_ASSUMED_APPLIED"]},"position":8},{"id":"v5-portuguese-compare-sources-25","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"SCHOOL_CLOSURE","statement":"Direção: “A aula da tarde foi suspensa por manutenção”. Calendário: “Atividades da manhã mantidas”.\n\nQual síntese não extrapola?","options":["A suspensão informada vale à tarde; o calendário mantém as atividades da manhã.","A escola ficou fechada o dia inteiro.","A manutenção começou de manhã.","Todas as atividades foram canceladas."],"correctAnswer":"A suspensão informada vale à tarde; o calendário mantém as atividades da manhã.","explanation":"Os recortes temporais são distintos e compatíveis.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"TIME_PERIOD_OMITTED","misconceptions":{"A escola ficou fechada o dia inteiro.":["TIME_PERIOD_OMITTED"]},"position":1},{"id":"v5-portuguese-compare-sources-26","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"REVISE_CLAIM","contextFamily":"ART_EXHIBITION","statement":"Curadoria: “Mostra reúne obras de três décadas”. Visitante: “Reconheci temas em várias salas”.\n\nQual fonte permite contar as décadas da mostra?","options":["O comentário, por mencionar salas.","A curadoria; o comentário registra uma leitura temática, não uma contagem temporal.","As duas igualmente.","Nenhuma, pois visitante não observa temas."],"correctAnswer":"A curadoria; o comentário registra uma leitura temática, não uma contagem temporal.","explanation":"Cada fonte sustenta afirmações diferentes.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"THEMATIC_OBSERVATION_USED_FOR_DATE","misconceptions":{"O comentário, por mencionar salas.":["THEMATIC_OBSERVATION_USED_FOR_DATE"]},"position":2},{"id":"v5-portuguese-compare-sources-27","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"PARK_TREE","statement":"Inventário: “42 árvores na área vistoriada”. Moradora: “Há sombra no banco da entrada à tarde”.\n\nQue limite acompanha a comparação?","options":["As 42 árvores garantem sombra em todo banco.","Todas as árvores ficam na entrada.","O inventário cobre a área vistoriada; o relato descreve lugar e período específicos.","A contagem informa sombra o dia inteiro."],"correctAnswer":"O inventário cobre a área vistoriada; o relato descreve lugar e período específicos.","explanation":"Quantidade não informa distribuição nem efeito sem outros dados.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"COUNT_CONFUSED_WITH_DISTRIBUTION","misconceptions":{"As 42 árvores garantem sombra em todo banco.":["COUNT_CONFUSED_WITH_DISTRIBUTION"]},"position":3},{"id":"v5-portuguese-compare-sources-28","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"REVISE_CLAIM","contextFamily":"ONLINE_NOTICE","statement":"Página institucional: “Inscrições até 30 de junho”. Captura sem endereço ou data: “Inscrições encerradas”.\n\nQual primeiro passo resolve a divergência?","options":["Escolher a mensagem mais curta.","Declarar a página desatualizada sem checar.","Somar as datas.","Verificar origem, data e versão da captura e consultar a página atual indicada pela instituição."],"correctAnswer":"Verificar origem, data e versão da captura e consultar a página atual indicada pela instituição.","explanation":"A captura sem procedência não pode ser situada no tempo.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"UNVERIFIED_CAPTURE_TREATED_AS_CURRENT","misconceptions":{"Escolher a mensagem mais curta.":["UNVERIFIED_CAPTURE_TREATED_AS_CURRENT"]},"position":4},{"id":"v5-portuguese-compare-sources-29","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"SPORTS_SCHEDULE","statement":"Quadro: “Treino às 15h no ginásio”. Mensagem: “Hoje será às 16h na quadra externa”.\n\nO que resolve a aparente divergência?","options":["A mensagem delimita uma alteração para hoje; o quadro pode indicar a programação habitual.","O treino foi cancelado.","O quadro torna a mensagem falsa.","Os horários devem ser somados."],"correctAnswer":"A mensagem delimita uma alteração para hoje; o quadro pode indicar a programação habitual.","explanation":"Uma regra habitual e uma mudança datada podem coexistir.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"SCHEDULE_CHANGE_MISTAKEN_FOR_CONTRADICTION","misconceptions":{"O treino foi cancelado.":["SCHEDULE_CHANGE_MISTAKEN_FOR_CONTRADICTION"]},"position":5},{"id":"v5-portuguese-compare-sources-30","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"REVISE_CLAIM","contextFamily":"WASTE_COLLECTION","statement":"Folheto: “Coleta seletiva às quartas”. Registro: “Coleta realizada quinta, dia 12, por mudança de feriado”.\n\nQual leitura é adequada?","options":["A coleta ocorre sempre quinta.","O folheto informa o dia habitual; o registro descreve uma exceção datada.","O serviço deixou de existir.","Uma fonte precisa ser falsa."],"correctAnswer":"O folheto informa o dia habitual; o registro descreve uma exceção datada.","explanation":"Regra geral e exceção temporal são compatíveis quando os recortes aparecem.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"EXCEPTION_GENERALIZED_AS_RULE","misconceptions":{"A coleta ocorre sempre quinta.":["EXCEPTION_GENERALIZED_AS_RULE"]},"position":6},{"id":"v5-portuguese-compare-sources-31","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"SYNTHESIZE","contextFamily":"LIBRARY_LOANS","statement":"Relatório: “210 empréstimos em maio”. Leitora: “Não encontrei o título procurado”.\n\nO que o total não prova?","options":["Que houve 210 empréstimos.","Que a leitora não encontrou um título.","Que cada título estava disponível ou que toda pessoa encontrou o que procurava.","Que o relatório cobre maio."],"correctAnswer":"Que cada título estava disponível ou que toda pessoa encontrou o que procurava.","explanation":"Total agregado não informa disponibilidade de cada título nem cada experiência.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"AGGREGATE_COUNT_USED_FOR_ITEM_AVAILABILITY","misconceptions":{"Que houve 210 empréstimos.":["AGGREGATE_COUNT_USED_FOR_ITEM_AVAILABILITY"]},"position":1},{"id":"v5-portuguese-compare-sources-32","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"WATER_SAMPLE","statement":"Laudo didático: “A amostra do ponto A estava dentro do parâmetro medido”. Relato: “Água no ponto B tinha cor diferente”.\n\nQual conclusão é proporcional?","options":["Toda água da região está adequada.","A cor prova contaminação.","O laudo invalida o relato.","O laudo descreve a amostra A; a observação B requer análise própria e não identifica causa."],"correctAnswer":"O laudo descreve a amostra A; a observação B requer análise própria e não identifica causa.","explanation":"Pontos e evidências diferem; uma amostra não representa automaticamente outro local.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"SAMPLE_SITE_GENERALIZED","misconceptions":{"Toda água da região está adequada.":["SAMPLE_SITE_GENERALIZED"]},"position":2},{"id":"v5-portuguese-compare-sources-33","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"TRANSFER","contextFamily":"COMMUNITY_POLL","statement":"Resumo: “58% dos 120 respondentes apoiaram a proposta”. Ata: “Votação formal adiada”.\n\nO que o apoio da pesquisa representa?","options":["A opinião dos respondentes naquele levantamento, não uma decisão formal do conselho.","A proposta foi aprovada.","Toda a comunidade apoiou.","A votação formal ocorreu na pesquisa."],"correctAnswer":"A opinião dos respondentes naquele levantamento, não uma decisão formal do conselho.","explanation":"Pesquisa de opinião e decisão institucional são procedimentos distintos.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"POLL_CONFUSED_WITH_DECISION","misconceptions":{"A proposta foi aprovada.":["POLL_CONFUSED_WITH_DECISION"]},"position":3},{"id":"v5-portuguese-compare-sources-34","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"SYNTHESIZE","contextFamily":"CLASSROOM_NOISE","statement":"Medição: “Média de 48 dB por dez minutos”. Relato: “Conversa ficou difícil durante a atividade”.\n\nComo sintetizar sem apagar uma fonte?","options":["48 dB prova que ninguém teve dificuldade.","A medição resume um intervalo; o relato descreve uma dificuldade situada que pode exigir observar aquele momento.","O relato prova que a média está errada.","A medição vale para todo horário escolar."],"correctAnswer":"A medição resume um intervalo; o relato descreve uma dificuldade situada que pode exigir observar aquele momento.","explanation":"Média temporal e experiência localizada podem coexistir; confira janela e atividade.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"AVERAGE_ERASES_LOCAL_VARIATION","misconceptions":{"48 dB prova que ninguém teve dificuldade.":["AVERAGE_ERASES_LOCAL_VARIATION"]},"position":4},{"id":"v5-portuguese-compare-sources-35","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"ACCESSIBLE_FILE","statement":"Página: “Material disponível em formato digital”. Estudante: “O arquivo não funciona com meu leitor de tela”.\n\nQue evidência adicional avalia acessibilidade?","options":["Formato digital prova acessibilidade.","A experiência deve ser ignorada.","Testar estrutura, navegação e alternativas textuais com tecnologias assistivas.","Arquivo digital não pode ter barreiras."],"correctAnswer":"Testar estrutura, navegação e alternativas textuais com tecnologias assistivas.","explanation":"Disponibilidade digital não garante compatibilidade nem acesso efetivo.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"DIGITAL_FORMAT_ASSUMED_ACCESSIBLE","misconceptions":{"Formato digital prova acessibilidade.":["DIGITAL_FORMAT_ASSUMED_ACCESSIBLE"]},"position":5},{"id":"v5-portuguese-compare-sources-36","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"TRANSFER","contextFamily":"TRAINING_CERTIFICATE","statement":"Certificado: “Participou de oficina de quatro horas”. Relato: “Agora uso a planilha básica”.\n\nO certificado não sustenta qual conclusão?","options":["Que participou da oficina.","Que relata aprendizagem específica.","Que a duração foi registrada.","Que a pessoa domina todas as funções ou mantém desempenho em qualquer tarefa."],"correctAnswer":"Que a pessoa domina todas as funções ou mantém desempenho em qualquer tarefa.","explanation":"Presença e domínio amplo são evidências diferentes; uma tarefa demonstrativa avalia habilidade específica.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"ATTENDANCE_MISTAKEN_FOR_MASTERY","misconceptions":{"Que participou da oficina.":["ATTENDANCE_MISTAKEN_FOR_MASTERY"]},"position":6},{"id":"v5-portuguese-compare-sources-37","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"LOCAL_HISTORY","statement":"Placa: “Estação inaugurada em 1932”. Entrevista hipotética: “Minha família começou a usá-la nos anos 1950”.\n\nPor que as informações podem coexistir?","options":["Uma data indica inauguração; a outra situa o início da experiência daquela família.","A estação não existia em 1932.","Todos começaram a usar em 1932.","Uma data precisa ser falsa."],"correctAnswer":"Uma data indica inauguração; a outra situa o início da experiência daquela família.","explanation":"Os referentes são diferentes: inauguração e experiência familiar.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"DATES_WITH_DIFFERENT_REFERENTS_COLLAPSED","misconceptions":{"A estação não existia em 1932.":["DATES_WITH_DIFFERENT_REFERENTS_COLLAPSED"]},"position":7},{"id":"v5-portuguese-compare-sources-38","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"PUBLIC_NOTICE","statement":"Edital: “Inscrição exige documento com foto”. Resposta de atendimento: “Meu documento digital foi aceito”.\n\nO caso individual não determina o quê?","options":["Que houve aceitação naquele atendimento.","Se toda versão digital é aceita em todos os casos e canais.","Que o edital tem uma exigência.","Que ambos tratam de inscrição."],"correctAnswer":"Se toda versão digital é aceita em todos os casos e canais.","explanation":"Um caso não estabelece regra geral; validade depende da norma e do canal.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"SINGLE_CASE_USED_AS_POLICY","misconceptions":{"Que houve aceitação naquele atendimento.":["SINGLE_CASE_USED_AS_POLICY"]},"position":8},{"id":"v5-portuguese-compare-sources-39","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"TRANSFER","contextFamily":"GARDEN_WATER","statement":"Plano: “Regar às 7h”. Registro: “Na terça, a equipe regou às 8h15 por falta de água”.\n\nQual explicação é apoiada?","options":["O horário mudou permanentemente.","O plano nunca foi usado.","O plano define o horário previsto; o registro descreve uma alteração naquela terça, com motivo.","A falta ocorreu todos os dias."],"correctAnswer":"O plano define o horário previsto; o registro descreve uma alteração naquela terça, com motivo.","explanation":"O registro contextualiza uma exceção datada, não uma mudança permanente.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"DATED_EXCEPTION_GENERALIZED","misconceptions":{"O horário mudou permanentemente.":["DATED_EXCEPTION_GENERALIZED"]},"position":9},{"id":"v5-portuguese-compare-sources-40","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"BUS_CAPACITY","statement":"Ficha: “Capacidade de 40 passageiros sentados”. Contagem: “Havia 33 pessoas a bordo no horário observado”.\n\nO que a ficha não informa?","options":["A capacidade declarada.","A contagem daquele horário.","Que os dados tratam do veículo.","Quantas pessoas estavam no veículo em outros horários ou se havia passageiros em pé."],"correctAnswer":"Quantas pessoas estavam no veículo em outros horários ou se havia passageiros em pé.","explanation":"Especificação e observação são dados diferentes; nenhum descreve outros horários.","hint":"Identifique o que cada fonte registra diretamente. Compare local, período, gênero e alcance; limite a conclusão ao que está explícito.","errorFocus":"SPECIFICATION_CONFUSED_WITH_OBSERVATION","misconceptions":{"A capacidade declarada.":["SPECIFICATION_CONFUSED_WITH_OBSERVATION"]},"position":10},{"id":"v30-portuguese-compare-sources-001","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"V30_PORTUGUESE_COMPARE_SOURCES_ADVERTISEMENT_01","statement":"Um anúncio diz que um curso “garante aprovação”, enquanto uma reportagem apresenta dados de matrículas e não informa resultados. Que comparação é responsável?","options":["Distinguir a promessa do anúncio dos dados apresentados pela reportagem e procurar evidência de resultados antes de aceitar a garantia.","A reportagem confirma a garantia porque menciona matrículas.","Toda propaganda é falsa e nenhum dado precisa ser consultado.","O verbo “garante” prova que todos serão aprovados."],"correctAnswer":"Distinguir a promessa do anúncio dos dados apresentados pela reportagem e procurar evidência de resultados antes de aceitar a garantia.","explanation":"Comparar fontes exige verificar alcance, gênero, período e evidência antes de generalizar. Promessa publicitária e dado descritivo têm funções diferentes; a conclusão precisa ser sustentada por evidência compatível.","hint":"Identifique o que cada fonte registra diretamente e limite a conclusão ao recorte indicado.","e